import{_ as s,o as e,c as t,a2 as i}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"备份自己的业务并验证独立恢复","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/backup-restore","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/backup-restore.md","filePath":"tutorials/backup-restore.md"}'),n={name:"tutorials/backup-restore.md"};function r(p,a,o,d,l,c){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="备份自己的业务并验证独立恢复" tabindex="-1">备份自己的业务并验证独立恢复 <a class="header-anchor" href="#备份自己的业务并验证独立恢复" aria-label="Permalink to &quot;备份自己的业务并验证独立恢复&quot;">​</a></h1><p>部署完成后，需要证明自己的业务数据、Files 对象和排队任务能够一起恢复。Backup Archive 是维护窗口内的数据库一致性快照、已核对的 ready 对象、清单和报告；文档导出或直接复制卷目录都不能替代它。</p><p>本指南需要已部署的生产组合、Docker Compose、受保护的环境文件和足够的归档空间。所有命令在仓库根目录运行。备份会停止应用写入者，恢复会创建新的持久卷。</p><h2 id="让自己的业务进入备份合同" tabindex="-1">让自己的业务进入备份合同 <a class="header-anchor" href="#让自己的业务进入备份合同" aria-label="Permalink to &quot;让自己的业务进入备份合同&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据位置</th><th>备份责任</th></tr></thead><tbody><tr><td>本部署 PostgreSQL 中的业务 schema</td><td>随完整数据库 dump 保存，包括迁移历史、Session、Job 和 Audit</td></tr><tr><td>通过 Files 发布的 ready 对象</td><td>按 <code>saas_core.files</code> 的键、大小与 sha256 核对，下载后入档</td></tr><tr><td>pending 上传</td><td>暂存对象不入档；恢复后按 TTL 过期，由幂等清理任务处理</td></tr><tr><td>自行引入的外部数据库或直接写入对象</td><td>当前工具不覆盖；扩展清单、核对与演练后才能承诺恢复</td></tr><tr><td>密钥与部署配置</td><td>不入档；由部署方独立、安全地提供</td></tr></tbody></table><p>新增业务应通过 Files 管理文件状态，让对象内容不可变、归属明确。归档包含数据库中的业务数据，虽然不含部署密钥，也需要访问控制与保留策略。</p><h2 id="停写、排空并创建归档" tabindex="-1">停写、排空并创建归档 <a class="header-anchor" href="#停写、排空并创建归档" aria-label="Permalink to &quot;停写、排空并创建归档&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p>可用第二个位置参数指定归档目录：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backups/release-before-upgrade</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/production-backup.mjs" target="_blank" rel="noreferrer">备份脚本</a>先停止 API，要求日志出现 <code>draining HTTP requests</code> 并在 25 秒前退出，低于 Compose 的 30 秒宽限期；随后停止 Worker，要求 <code>stopping worker claims and draining current work</code> 并在 40 秒前退出，低于 45 秒宽限期。达到停止预算或对象核对失败会让备份失败。数据库中的 queued Job 保留，窗口内不继续认领。</p><p>写入者停止后，工具执行 <code>pg_dump -Fc</code>，读取 ready 文件登记，逐个下载并核对 sha256 和大小。多余未引用对象记录在报告中；缺失或不符的 ready 对象使归档不一致。</p><p>归档内应有：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>database.dump</span></span>
<span class="line"><span>manifest.json</span></span>
<span class="line"><span>objects/</span></span>
<span class="line"><span>backup-report.md</span></span></code></pre></div><p><code>manifest.json</code> 记录应用镜像/digest、迁移版本和对象清单。检查报告 PASS 与明细后，可用 <code>just production-up .env.production</code> 恢复原栈运行。</p><h2 id="在独立空环境恢复" tabindex="-1">在独立空环境恢复 <a class="header-anchor" href="#在独立空环境恢复" aria-label="Permalink to &quot;在独立空环境恢复&quot;">​</a></h2><p>停止生产组合以释放 80/443，保留其卷：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-down</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backups/release-before-upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p>Restore Environment 默认使用不同的 Compose 项目名、新网络和新卷；工具拒绝与生产相同的项目名。停止生产组合仅释放端口，不要求删除生产数据。恢复后是否切换流量是一个显式部署决定，工具不会替你覆盖生产卷。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/production-restore.mjs" target="_blank" rel="noreferrer">恢复脚本</a>依次启动依赖、执行 <code>pg_restore --no-owner --exit-on-error</code>、初始化桶、启动 Caddy、按清单上传对象，再启动 API/Worker。准备归档对应的镜像与受保护配置；它不会自动下载历史镜像，也不会隐式执行新迁移。</p><p>最终检查 readiness、迁移版本与桶清单，写 <code>restore-report.md</code>，保留恢复栈供检查。如果 <code>pg_restore</code> 失败，目标可能已部分写入：销毁这个失败的独立恢复项目后重新创建，不要向同一半成品库反复叠加恢复。</p><h2 id="给自己的业务增加恢复断言" tabindex="-1">给自己的业务增加恢复断言 <a class="header-anchor" href="#给自己的业务增加恢复断言" aria-label="Permalink to &quot;给自己的业务增加恢复断言&quot;">​</a></h2><p>结构核对通过后，从真实 HTTPS API 验证至少一个完整业务结果：</p><ol><li>恢复前创建具有已知字段值的资源，记录其 id、版本和可访问账号。</li><li>若业务有文件，上传已知字节并完成发布。</li><li>停 Worker 后通过公开 API 排队一个任务，再备份。</li><li>恢复后登录或使用恢复的 Session，读取资源并比对字段、版本和文件字节。</li><li>等 Worker 完成原 queued Job，读取业务结果；验证失败/撤权路径不会额外发布对象。</li><li>在演练中让 pending 上传到期，确认其终态与暂存对象清理。</li></ol><p>现有<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/scripts/production-restore-drill.mjs" target="_blank" rel="noreferrer">自动演练</a>用参考应用验证同一条备份/恢复命令：账号、文档、附件逐字节、排队导出、pending 到期和清理。它会创建测试项目及密钥，结束删除自己的卷、环境文件与临时证书，把报告留在 <code>.scratch/</code>；需要空闲 80/443。读者新增业务不自动包含在此旅程中，应按上面的行为加入断言。</p><h2 id="检查与排错" tabindex="-1">检查与排错 <a class="header-anchor" href="#检查与排错" aria-label="Permalink to &quot;检查与排错&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/backup-sigv4.test.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/backup-manifest.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-restore-drill</span></span></code></pre></div><p>清单检查和 SigV4 测试无需 Docker；演练使用真实生产组合。端口冲突时先确认哪个组合在占用；不要用删除卷解决监听冲突。对象不符时保留报告，检查 Files 登记与实际对象。缺失部署密钥时从受保护配置恢复，不能从归档推导。</p><p>这些工具属于 SaaS Core；移除参考业务不会移除备份/恢复能力。下一步：<a href="./../testing/feedback-loop">把自己的恢复断言接入测试反馈循环</a>。</p><hr><p>源码版本：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/tutorials/22-backup-restore.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,31)])])}const u=s(n,[["render",r]]);export{k as __pageData,u as default};
